# Verify the bookmark-storage pilot

Run `node <target-root>/scripts/run.mjs initialize --project <project-root>` first.

- On `RECORD_INITIALIZED`, read every returned current `inputs[].absolutePath`, then read the returned `domainConfig`. Do not inspect runtime source or look for a prepared packet.
- Run the exact verification command declared by `domainConfig.verificationCommand` from its declared project-relative `cwd`.
- Decide whether the evidence justifies `pass`, `fail`, or `unproven` for the declared `cardId`: pass requires the command to succeed and report the expected test identity; a command execution failure, an unexecuted command, an unknown card identity, or insufficient evidence is unproven; use fail only for direct evidence that the acceptance behavior does not hold.
- Fill the returned `answer` JSON without adding fields. Preserve unknown reasons and do not claim file or host effects beyond the authority actually observed, then run the returned exact `recordCommand`.
- If `recordCommand` exits without one valid JSON result, retry that exact command once; a write that already succeeded returns `APPLIED_ALREADY`. Never reconstruct or edit the output manually.
- On initialize, integrity, answer, stale, conflict, lock, renderer, or apply errors, perform only the returned `nextAction`. Never repair generated files or merge report bytes by hand.

Done means record returns an observed `APPLIED`, idempotent `APPLIED_ALREADY`, or a fail-closed recovery result without overstating semantic or effect authority. Build delivery, AI behavior, semantic correctness, and observed file effect are separate evidence lanes; anything not observed in its proper lane remains `unproven`.

#!/usr/bin/env node
import { TextDecoder } from "node:util";

const decoder = new TextDecoder("utf-8", { fatal: true });
const START = "<!-- skill-rails-next:verify-records:start -->";
const END = "<!-- skill-rails-next:verify-records:end -->";
const RECORD_PREFIX = "<!-- skill-rails-next:verify-record:";

function compareCodePoint(a, b) {
  const left = Array.from(a); const right = Array.from(b);
  for (let index = 0; index < Math.min(left.length, right.length); index += 1) { const difference = left[index].codePointAt(0) - right[index].codePointAt(0); if (difference) return difference; }
  return left.length - right.length;
}

function canonicalJson(value) {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  return `{${Object.keys(value).sort(compareCodePoint).map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(",")}}`;
}

function inline(value) {
  return value.replace(/[\r\n]+/g, " ").replace(/([\\`*_[\]<>])/g, "\\$1");
}

function recordBytes(answer) {
  const encoded = Buffer.from(canonicalJson(answer), "utf8").toString("base64url");
  const checks = answer.checks.map((check) => {
    const evidence = check.evidence.length ? check.evidence.map((item) => `${item.authority}: ${item.reference}`).join("; ") : "no cited evidence";
    return `- ${inline(check.name)}: ${check.outcome} — ${inline(evidence)}`;
  });
  const unknowns = answer.unknowns.length ? answer.unknowns.map((item) => inline(item)).join("; ") : "none";
  return [
    `${RECORD_PREFIX}${encoded} -->`,
    `### ${inline(answer.cardId)} — ${answer.verdict}`,
    "",
    inline(answer.summary),
    "",
    ...checks,
    `- Unknowns: ${unknowns}`,
  ].join("\n");
}

function region(records) {
  const bodies = [...records.values()].sort((a, b) => compareCodePoint(a.cardId, b.cardId)).map(recordBytes);
  return [START, ...bodies.flatMap((body) => [body, ""]), END].join("\n").replace(/\n\n<!-- skill-rails-next:verify-records:end -->$/, "\n<!-- skill-rails-next:verify-records:end -->");
}

function locate(text) {
  const matches = [...text.matchAll(/^<!-- skill-rails-next:([a-z0-9]+(?:-[a-z0-9]+)*):(start|end) -->\r?$/gm)];
  if (matches.length === 0) return null;
  if (matches.length !== 2 || matches[0][1] !== "verify-records" || matches[0][2] !== "start" || matches[1][1] !== "verify-records" || matches[1][2] !== "end" || matches[0].index >= matches[1].index) throw new Error("MANAGED_REGION_INVALID");
  const endMarkerLength = matches[1][0].endsWith("\r") ? matches[1][0].length - 1 : matches[1][0].length;
  return { start: matches[0].index, end: matches[1].index + endMarkerLength, eol: text.slice(matches[0].index, matches[1].index).includes("\r\n") ? "\r\n" : "\n" };
}

function parseExisting(text, location) {
  if (!location) return new Map();
  const currentRegion = text.slice(location.start, location.end).replace(/\r\n/g, "\n");
  const records = new Map();
  for (const match of currentRegion.matchAll(/^<!-- skill-rails-next:verify-record:([A-Za-z0-9_-]+) -->$/gm)) {
    let answer;
    try { answer = JSON.parse(Buffer.from(match[1], "base64url").toString("utf8")); } catch { throw new Error("MANAGED_REGION_INVALID"); }
    if (!answer?.cardId || records.has(answer.cardId)) throw new Error("MANAGED_REGION_INVALID");
    records.set(answer.cardId, answer);
  }
  if (currentRegion !== region(records)) throw new Error("MANAGED_REGION_INVALID");
  return records;
}

const chunks = [];
for await (const chunk of process.stdin) chunks.push(chunk);
try {
  const request = JSON.parse(Buffer.concat(chunks).toString("utf8"));
  const current = decoder.decode(Buffer.from(request.currentOutputBase64, "base64"));
  const location = locate(current);
  const records = parseExisting(current, location);
  records.set(request.validatedAnswer.cardId, request.validatedAnswer);
  const desiredRegion = location?.eol === "\r\n" ? region(records).replace(/\n/g, "\r\n") : region(records);
  let desired;
  if (location) desired = `${current.slice(0, location.start)}${desiredRegion}${current.slice(location.end)}`;
  else if (current.length === 0) desired = `${desiredRegion}\n`;
  else desired = `${current}${current.endsWith("\n") ? "\n" : "\n\n"}${desiredRegion}\n`;
  process.stdout.write(desired);
} catch (error) {
  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
  process.exitCode = 1;
}

# Purpose

Verify the declared bookmark-storage capability against its acceptance evidence and preserve prior verification records. Report uncertainty as `unproven`; never turn a structural check or an unexecuted command into proof of behavior or effect.

# Verify control baseline

Verify the `bookmark-storage` card using only the declared project files and host tools you are authorized to use.

1. Read `pilot/brief.md`, `pilot/plan.md`, `pilot/progress.md`, and the current `pilot/verification.md` when it exists.
2. Confirm that the card identity is `bookmark-storage` and distinguish stated progress from observed evidence.
3. Run `npm test -- bookmark-storage` from the project root when host permission allows it. Do not infer a pass from file structure or prose.
4. Decide `pass`, `fail`, or `unproven`. A pass requires cited command evidence; missing or insufficient evidence remains `unproven`.
5. Preserve all human-authored bytes and other card records. Update only the `bookmark-storage` record inside the Skill Rails Next managed region.
6. Label evidence authority accurately. A report written by an AI is `ai-reported` until an authorized host observation supports a stronger claim.

If safe preservation, currentness, or authority cannot be established, do not write the report and explain the unresolved boundary.

